    for (let btn of allButtons) {
      const text = await btn.getText();
      if (text.includes('Explore') || text.includes('Start Tour')) {
        exploreButton = btn;
        attempts.push(`Found button with text: "${text}"`);
        break;
      }
    }
  } catch (e) {
    attempts.push('Text search: failed');
  }
